<script>
// --- Simulated page-detail lookup (prototype only) ---
// Stands in for the real "fetch the page's details" behaviour so we can explore
// the flow without a live server. Returns plausible details from the address.
const CANNED = {
  "nytimes.com":   { title:"The Science of a Good Night's Sleep", desc:"How small evening habits change how rested you feel.", site:"The New York Times" },
  "github.com":    { title:"tldr-pages/tldr: Simplified man pages", desc:"Community-maintained help pages for command-line tools.", site:"GitHub" },
  "wikipedia.org": { title:"Bookmark (digital) — Wikipedia", desc:"A saved shortcut used to return to a web page later.", site:"Wikipedia" },
  "medium.com":    { title:"Designing Calm Software", desc:"An essay on interfaces that respect your attention.", site:"Medium" }
};
function domainOf(url){
  try { return new URL(url).hostname.replace(/^www\./,""); } catch(e){ return ""; }
}
function lookup(url){
  const host = domainOf(url);
  for (const key in CANNED){ if (host.endsWith(key)) return { ...CANNED[key], site: CANNED[key].site }; }
  // generic fallback derived from the address
  const path = (function(){ try { return new URL(url).pathname; } catch(e){ return ""; } })();
  const slug = path.split("/").filter(Boolean).pop() || host;
  const pretty = slug.replace(/[-_]+/g," ").replace(/\.\w+$/,"").replace(/\b\w/g, c=>c.toUpperCase());
  return { title: pretty || host, desc:"", site: host };
}

const bookmarks = [];
const $ = id => document.getElementById(id);

function refreshSaveState(){
  const hasUrl = $("url").value.trim() !== "";
  const hasTitle = $("title").value.trim() !== "";
  $("saveBtn").disabled = !(hasUrl && hasTitle);
}

$("fetchBtn").addEventListener("click", () => {
  const url = $("url").value.trim();
  const note = $("fetchNote");
  if (!url){ note.textContent = "Paste a web address first."; note.className="fetch-note"; return; }
  const d = lookup(url);
  $("title").value = d.title;
  $("desc").value = d.desc;
  note.textContent = d.desc || d.title ? "Details filled in automatically — edit anything you like." : "Couldn't read details; please type them in.";
  note.className = "fetch-note filled";
  refreshSaveState();
});

["url","title"].forEach(id => $(id).addEventListener("input", refreshSaveState));

$("saveBtn").addEventListener("click", () => {
  const bm = {
    url: $("url").value.trim(),
    title: $("title").value.trim(),
    desc: $("desc").value.trim(),
    tags: $("tags").value.split(",").map(t=>t.trim()).filter(Boolean),
    note: $("note").value.trim(),
    site: domainOf($("url").value.trim())
  };
  bookmarks.unshift(bm);
  render();
  // reset form
  ["url","title","desc","tags","note"].forEach(id => $(id).value="");
  $("fetchNote").textContent=""; $("fetchNote").className="fetch-note";
  refreshSaveState();
  const f = $("flash"); f.textContent = "Saved. It's now in your list below."; f.style.display="block";
  setTimeout(()=>{ f.style.display="none"; }, 3000);
});

function render(){
  const list = $("list"); list.innerHTML="";
  $("count").textContent = bookmarks.length ? bookmarks.length + (bookmarks.length===1?" link":" links") : "";
  $("empty").style.display = bookmarks.length ? "none" : "block";
  bookmarks.forEach(bm => {
    const li = document.createElement("li"); li.className="bm-item";
    li.innerHTML =
      '<p class="title"><a href="'+bm.url+'" target="_blank" rel="noopener">'+escapeHtml(bm.title)+'</a></p>'+
      '<div class="site">'+escapeHtml(bm.site)+'</div>'+
      (bm.desc ? '<p class="desc">'+escapeHtml(bm.desc)+'</p>' : '')+
      (bm.tags.length ? '<div class="tags">'+bm.tags.map(t=>'<span class="tag">'+escapeHtml(t)+'</span>').join('')+'</div>' : '')+
      (bm.note ? '<div class="note">'+escapeHtml(bm.note)+'</div>' : '');
    list.appendChild(li);
  });
}
function escapeHtml(s){ return (s||"").replace(/[&<>"']/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])); }

render();
document.body.setAttribute("data-harness-ready","true");
